class SkillIndex:
    """skills/index.json: one entry per skill, newest last."""

    def __init__(self, path: Path):
        self.path = path
        self.entries = json.loads(path.read_text()) if path.exists() else []

    @classmethod
    def at(cls, root: Path) -> "SkillIndex":
        return cls(root / "index.json")

    def record(self, meta: SkillMeta) -> None:
        self.entries = [e for e in self.entries if e["name"] != meta.name]
        self.entries.append(
            {
                "name": meta.name,
                "description": meta.description,
                "entry": meta.entry,
                "added": meta.added.isoformat(),
            }
        )
        self.path.write_text(json.dumps(self.entries, indent=2))

    def forget(self, name: str) -> None:

