from .schema import Schema
from .errors import RowError


class Checked(NamedTuple):
    good: list[Row]
    bad: list[tuple[Row, str]]


def check_batch(rows: list[Row], schema: Schema) -> Checked:
    good, bad = [], []
    for row in rows:
        try:
            check_row(row, schema)
            good.append(row)
        except RowError as error:
            bad.append((row, str(error)))
    return Checked(good, bad)


def check_row(row: Row, schema: Schema) -> None:
    for field in schema.required:
        if row.get(field) in (None, ""):
            raise RowError(f"missing {field}")
    for field, kind in schema.types.items():
        if field in row and not isinstance(row[field], kind):
            raise RowError(f"{field} is not {kind.__name__}")
    if schema.unique and row["id"] in schema.seen:
        raise RowError(f"duplicate id {row['id']}")
    schema.seen.add(row["id"])

from datetime import datetime


def normalize(row: Row) -> Row:
    out = {k: v.strip() if isinstance(v, str) else v for k, v in row.items()}
    if "email" in out:
        out["email"] = out["email"].lower()
    if "created" in out:
        out["created"] = datetime.fromisoformat(out["created"])
    return Row(**out)

from .db import table, transaction

ROWS = table("rows")


@transaction
def write_rows(rows: list[Row]) -> int:
    ROWS.insert_many([r.model_dump() for r in rows])
    return len(rows)
